// Extract message data
const payload = msg.payload || {};
let chatId = payload.chatId;
const messageType = payload.type;
let text = (payload.content || '').trim();

// Get user info
const originalMsg = msg.originalMessage || {};
let userId = originalMsg.from ? originalMsg.from.id : null;
const messageId = originalMsg.message_id;

// Handle callback queries
let answerCallback = null;
if (messageType === 'callback_query') {
    text = payload.data || payload.callback_data || payload.content || 
           (originalMsg.data ? originalMsg.data : '') || '';

    if (!chatId) {
        if (originalMsg.message && originalMsg.message.chat) {
            chatId = originalMsg.message.chat.id;
        } else if (originalMsg.chat) {
            chatId = originalMsg.chat.id;
        }
    }

    if (originalMsg.from) {
        userId = originalMsg.from.id;
    }

    const callbackQueryId = payload.callback_query_id || payload.id || 
                            (originalMsg.id ? originalMsg.id.toString() : null) ||
                            (originalMsg.query_id ? originalMsg.query_id.toString() : null);

    if (callbackQueryId) {
        answerCallback = {
            payload: {
                callback_query_id: callbackQueryId,
                text: '',
                show_alert: false
            },
            topic: 'answerCallbackQuery'
        };
    }
}

// Check if it's a sliding gate command
if ((messageType !== 'message' && messageType !== 'callback_query') || !text || !chatId) {
    return [null, answerCallback].filter(m => m !== null);
}

// Store chat ID for notifications
if (!flow.get('sliding_telegram_chat_ids')) {
    flow.set('sliding_telegram_chat_ids', []);
}
const chatIds = flow.get('sliding_telegram_chat_ids');
if (!chatIds.includes(chatId)) {
    chatIds.push(chatId);
    flow.set('sliding_telegram_chat_ids', chatIds);
}

// Parse command
const command = text.split(' ')[0].toLowerCase();
const args = text.split(' ').slice(1);

// Only handle sliding gate commands
if (!command.startsWith('/sliding')) {
    return [null, answerCallback].filter(m => m !== null);
}

// Store telegram data
msg.telegram = {
    chatId: chatId,
    userId: userId,
    messageId: messageId,
    command: command,
    args: args,
    originalText: text
};

// Route to appropriate handler
if (command === '/sliding_open') {
    msg.topic = 'sliding_open';
} else if (command === '/sliding_close') {
    msg.topic = 'sliding_close';
} else if (command === '/sliding_trigger') {
    msg.topic = 'sliding_trigger';
} else if (command === '/sliding_status') {
    msg.topic = 'sliding_status';
} else if (command === '/sliding_help') {
    msg.topic = 'sliding_help';
} else {
    msg.topic = 'sliding_unknown';
}

return [msg, answerCallback].filter(m => m !== null);

if (msg.payload && msg.payload.callback_query_id) {
    msg.payload = {
        callback_query_id: msg.payload.callback_query_id,
        text: msg.payload.text || '',
        show_alert: msg.payload.show_alert || false
    };
    msg.topic = 'answerCallbackQuery';
    return msg;
}
return null;

// Create MQTT command
const timestamp = new Date().toISOString();
const requestId = `telegram-sliding-open-${Date.now()}`;

const telegramData = msg.telegram;

// Create MQTT message to trigger Relay 1 (Open)
msg.payload = true;
msg.topic = 'cmnd/automatizare_poarta/Power1';
msg.telegram = telegramData;
msg.telegram.requestId = requestId;

// Create confirmation message
const confirmationMsg = {
    ...msg,
    payload: {
        chatId: telegramData.chatId,
        type: 'message',
        content: `🔓 Opening Sliding Gate...\n\nRelay 1 activated (1 second pulse)\nRequest ID: ${requestId}`,
        parse_mode: 'Markdown'
    },
    topic: 'send'
};

// Send both MQTT command and Telegram confirmation
return [msg, confirmationMsg];

// Create MQTT command
const timestamp = new Date().toISOString();
const requestId = `telegram-sliding-close-${Date.now()}`;

const telegramData = msg.telegram;

// Create MQTT message to trigger Relay 2 (Close)
msg.payload = true;
msg.topic = 'cmnd/automatizare_poarta/Power2';
msg.telegram = telegramData;
msg.telegram.requestId = requestId;

// Create confirmation message
const confirmationMsg = {
    ...msg,
    payload: {
        chatId: telegramData.chatId,
        type: 'message',
        content: `🔒 Closing Sliding Gate...\n\nRelay 2 activated (1 second pulse)\nRequest ID: ${requestId}`,
        parse_mode: 'Markdown'
    },
    topic: 'send'
};

// Send both MQTT command and Telegram confirmation
return [msg, confirmationMsg];

// Create MQTT command
const timestamp = new Date().toISOString();
const requestId = `telegram-sliding-trigger-${Date.now()}`;

const telegramData = msg.telegram;

// Create MQTT message to trigger Relay 3 (Trigger)
msg.payload = true;
msg.topic = 'cmnd/automatizare_poarta/Power3';
msg.telegram = telegramData;
msg.telegram.requestId = requestId;

// Create confirmation message
const confirmationMsg = {
    ...msg,
    payload: {
        chatId: telegramData.chatId,
        type: 'message',
        content: `🔄 Triggering Sliding Gate...\n\nRelay 3 activated (1 second pulse)\nRequest ID: ${requestId}`,
        parse_mode: 'Markdown'
    },
    topic: 'send'
};

// Send both MQTT command and Telegram confirmation
return [msg, confirmationMsg];

// Get sliding gate state from flow context
const slidingState = flow.get('sliding_gate_state') || {};

let statusText = `🚪 *Sliding Gate Status*\n\n`;

// Relay states
statusText += '*Relays:*\n';
statusText += `Relay 1 (Open): ${slidingState.relay1 || 'UNKNOWN'}\n`;
statusText += `Relay 2 (Close): ${slidingState.relay2 || 'UNKNOWN'}\n`;
statusText += `Relay 3 (Trigger): ${slidingState.relay3 || 'UNKNOWN'}\n`;
statusText += `Relay 4 (Open Alt): ${slidingState.relay4 || 'UNKNOWN'}\n`;

// Last update
if (slidingState.lastUpdate) {
    const lastUpdate = new Date(slidingState.lastUpdate).toLocaleString('ro-RO');
    statusText += `\n🕐 Last update: ${lastUpdate}`;
}

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: statusText,
    parse_mode: 'Markdown'
};
msg.topic = 'send';

return msg;

const helpText = `🚪 *Sliding Gate Control Bot*\n\n` +
    `*Available Commands:*\n\n` +
    `🔓 \`/sliding_open\`\n` +
    `   Open the sliding gate (Relay 1)\n\n` +
    `🔒 \`/sliding_close\`\n` +
    `   Close the sliding gate (Relay 2)\n\n` +
    `🔄 \`/sliding_trigger\`\n` +
    `   Trigger gate automation (Relay 3)\n\n` +
    `📊 \`/sliding_status\`\n` +
    `   Get sliding gate status\n\n` +
    `❓ \`/sliding_help\`\n` +
    `   Show this help message\n\n` +
    `*Features:*\n` +
    `• 1-second pulse control\n` +
    `• Command history logging\n` +
    `• Request ID tracking\n\n` +
    `*Quick Actions:*\n` +
    `Use the buttons below:`;

const inlineKeyboard = {
    inline_keyboard: [
        [
            { text: '🔓 Open Sliding Gate', callback_data: '/sliding_open' }
        ],
        [
            { text: '🔒 Close Sliding Gate', callback_data: '/sliding_close' }
        ],
        [
            { text: '🔄 Trigger', callback_data: '/sliding_trigger' },
            { text: '📊 Status', callback_data: '/sliding_status' }
        ],
        [
            { text: '❓ Help', callback_data: '/sliding_help' }
        ]
    ]
};

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: helpText,
    parse_mode: 'Markdown',
    options: {
        reply_markup: JSON.stringify(inlineKeyboard)
    }
};
msg.topic = 'send';

return msg;

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: `❓ Unknown sliding gate command: ${msg.telegram.originalText}\n\nType /sliding_help for available commands.`
};
msg.topic = 'send';

return msg;
